// One live Telegram line per visitor per day, and one more when a new visitor
// turns out human. A first look only: the Bot Detector judges the whole day overnight.
// Your own networks, as address prefixes. Set in the n8n UI, never in the public copy.
const SELF_NETS = ['YOUR_HOME_NET_PREFIX.'];
// A new visitor from a place already announced this recently updates that line instead.
const GROUP_MIN = 10;
const v = $('Visit Webhook').first().json.body || {};
const ip = String(v.ip || '');
if (!ip || SELF_NETS.some((net) => ip.startsWith(net))) return [];

// Who was already announced today; yesterday's list is dropped on the first event of a day.
const day = String(v.ts || new Date().toISOString()).slice(0, 10);
const memory = $getWorkflowStaticData('global');
if (!memory.told || memory.told.day !== day || !memory.told.lines) memory.told = { day, visitors: {}, lines: {} };
const was = memory.told.visitors[ip] || '';

const where = [v.city, v.country].filter(Boolean).join(', ') || 'unknown place';
const ua = String(v.ua || '');
// The device, off the user agent; the same rule wherever a message says where a visitor is.
const deviceOf = (ua) => {
  const s = String(ua ?? '').trim();
  return !s ? '' : /iPad|Tablet/.test(s) ? 'tablet' : /Mobi|Android|iPhone/.test(s) ? 'phone' : 'computer';
};
// Several addresses: one word when every one agrees, a count of each known device when not.
const devicesText = (list) => {
  const t = {};
  for (const d of list) if (d) t[d] = (t[d] || 0) + 1;
  const e = Object.entries(t).sort((a, b) => b[1] - a[1]);
  return e.length === 1 && e[0][1] === list.length ? e[0][0] : e.map(([d, k]) => k + ' ' + d + (k === 1 ? '' : 's')).join(', ');
};
const device = deviceOf(ua);
const bot = Boolean(v.flag) || !/mozilla\//i.test(ua);
const net = ip.includes(':') ? ip.split(':').slice(0, 3).join(':') + '::' : ip.split('.').slice(0, 3).join('.') + '.x';
// A link click is stored as "label → href"; a bare control has no arrow and went nowhere.
const [label, href] = String(v.target || '').split(' → ');
const clicked = v.event !== 'pageview' && Boolean(href);
let from = '';
try { from = v.referrer ? new URL(v.referrer).hostname.replace(/^www\./, '') : ''; } catch { from = String(v.referrer).slice(0, 40); }

// A first sighting: a new line, or the place's recent line counted up. "×2" is two
// addresses, and what ties them is said when they share it.
const announce = (head, tail) => {
  const key = head + '|' + where;
  const line = memory.told.lines[key];
  const now = Date.now();
  if (line && line.id && now - line.at < GROUP_MIN * 60e3) {
    line.n += 1;
    line.nets = [...new Set([...line.nets, net])];
    line.uas = [...new Set([...line.uas, ua])];
    line.devices = [...(line.devices || []), device];
    const ties = [line.nets.length === 1 && 'same network', line.uas.length === 1 && 'same browser'].filter(Boolean).join(', ');
    return { text: [head + ' · ' + where + ' ×' + line.n, devicesText(line.devices), ties, line.tail].filter(Boolean).join(' · '), edit: line.id, key };
  }
  memory.told.lines[key] = { at: now, id: '', n: 1, nets: [net], uas: [ua], devices: [device], tail };
  return { text: [head, where, device, tail].filter(Boolean).join(' · '), edit: '', key };
};

let alert = null;
if (!was && bot) {
  const name = (ua.match(/[\w.-]*(bot|crawler|spider|indexer|fetcher)[\w./-]*/i) || [])[0] || v.flag || 'no browser named';
  alert = announce('🤖 Bot · ' + name, v.path || '/');
  memory.told.visitors[ip] = 'bot';
} else if (!was) {
  alert = announce('🆕 New visitor', (v.path || '/') + (from ? ` · from ${from}` : ''));
  memory.told.visitors[ip] = 'new';
} else if (was === 'new' && clicked) {
  alert = { text: ['🙋 Likely human', where, device, `clicked “${label.trim()}”`].filter(Boolean).join(' · '), edit: '', key: '' };
  memory.told.visitors[ip] = 'human';
}
return alert ? [{ json: alert }] : [];

// The sent line's id, so a visitor from the same place minutes later updates it.
const { key } = $('Decide Live Alert').first().json;
const line = key && ($getWorkflowStaticData('global').told?.lines || {})[key];
const sent = $input.first().json;
if (line) line.id = sent.result?.message_id || sent.message_id || '';
return [];
